//! 📥️ Two original UI slots remain pinned through bounded conversion, merge and cancellation.
use super::*;
/// 🧷️ The enclosing receiving owner retains its actual UI slots until this continuation restores both roots.
pub struct OriginalUiArguments{binding:OriginalSourceBinding,decoder:(u64,u64),slots:(usize,usize),body:usize,value:ManuallyDrop<Option<Box<OriginalUiValueConversion>>>,merge:ManuallyDrop<Option<Box<OriginalUiArgumentsMerge>>>,args:ManuallyDrop<Option<DslValue>>,input:ManuallyDrop<Option<DslValue>>,output:ManuallyDrop<Option<DslValue>>,retirement:RetainedCloneClose,phase:u8,closing:bool,taken:bool}
impl OriginalUiArguments{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 pub fn admit(args:&mut Option<UiValue>,input:&mut Option<UiValue>,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let binding=OriginalSourceBinding::borrow(cx);let slots=(args as*mut _ as usize,input as*mut _ as usize);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::birth_demands();admit_original_construction(cx,output,original(d),|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::write(Box::new_uninit(),Self{binding,decoder,slots,body,value:ManuallyDrop::new(None),merge:ManuallyDrop::new(None),args:ManuallyDrop::new(None),input:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false,taken:false}),receipt(d)))})}
 fn validate(&self,args:&mut Option<UiValue>,input:&mut Option<UiValue>,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if self.slots!=(args as*mut _ as usize,input as*mut _ as usize)||!self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 pub fn demands(&self,args:&Option<UiValue>,input:&Option<UiValue>)->Result<Option<RetirementDemand>,ValueError>{if self.closing{return self.close_demands().map(Some)}if self.phase<2{if let Some(value)=self.value.as_ref(){return if value.terminal_is_empty(){Ok(Some(Self::value_release_demands()))}else if value.ready(){value.take_demands().map(Some)}else{value.demands()}}let slot=if self.phase==0{args}else{input};return Ok(Some(if slot.is_some(){OriginalUiValueConversion::birth_demands()}else{header::<u8>()}))}if let Some(merge)=self.merge.as_ref(){if merge.ready(){merge.take_demands().map(Some)}else if merge.terminal_is_empty(){self.take_demands().map(Some)}else{merge.demands().map(Some)}}else{Ok(Some(OriginalUiArgumentsMerge::birth_demands()))}}
 fn value_release_demands()->RetirementDemand{let mut d=OriginalUiValueConversion::release_demands();d.copy_bytes=size_of::<u8>();d}
 pub fn ready(&self)->bool{!self.closing&&!self.taken&&self.phase==2&&self.merge.as_ref().is_some_and(|merge|merge.terminal_is_empty())}
 pub fn advance(&mut self,args:&mut Option<UiValue>,input:&mut Option<UiValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(args,input,cx)?;if self.closing||self.taken{return Err(invalid().into())}if self.ready(){return Ok(true)}if self.phase<2{let slot=if self.phase==0{args}else{input};if let Some(value)=self.value.as_mut(){if value.terminal_is_empty(){let d=Self::value_release_demands();let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{self.value.take();self.phase+=1;Ok(((),receipt(d)))})?;}else if value.ready(){value.take_into(if self.phase==0{&mut self.args}else{&mut self.input},cx)?;}else{value.advance(slot,cx)?;}return Ok(false)}if slot.is_some(){OriginalUiValueConversion::admit(slot,cx,&mut self.value)?;}else{let d=header::<u8>();let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{self.phase+=1;Ok(((),receipt(d)))})?;}return Ok(false)}if let Some(merge)=self.merge.as_mut(){if merge.ready(){merge.take_into(&mut self.output,cx)?;}else{merge.advance(cx)?;}}else{OriginalUiArgumentsMerge::admit(&mut self.args,&mut self.input,cx,&mut self.merge)?;}Ok(self.ready())}
 pub fn output_taken(&self)->bool{self.taken}
 pub fn take_demands(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid())}Ok(header::<(Option<DslValue>,Option<DslValue>,bool)>())}
 pub fn take_into(&mut self,output:&mut Option<DslValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder)||output.is_some(){return Err(invalid().into())}let d=self.take_demands()?;let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{*output=self.output.take();self.taken=true;Ok(((),receipt(d)))})}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if let Some(value)=self.value.as_ref(){return if value.terminal_is_empty(){Ok(OriginalUiValueConversion::release_demands())}else{value.close_demands()}}if let Some(merge)=self.merge.as_ref(){return if merge.terminal_is_empty(){Ok(OriginalUiArgumentsMerge::release_demands())}else{merge.close_demands()}}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}for present in [self.args.is_some(),self.input.is_some(),self.output.is_some()]{if present{return self.retirement.next_owner_demands::<DslValue>(true,&None,self.body)}}Ok(Default::default())}
 pub fn close_step(&mut self,args:&mut Option<UiValue>,input:&mut Option<UiValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(args,input,cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands()?;if !self.closing{close_original_retained_step(cx,d,|_|{self.closing=true;Ok(RetainedCloneStep::Progress(receipt(d)))})?;return Ok(false)}if let Some(value)=self.value.as_mut(){if value.terminal_is_empty(){close_original_retained_step(cx,d,|_|{self.value.take();Ok(RetainedCloneStep::Progress(receipt(d)))})?;}else{value.close_step(if self.phase==0{args}else{input},cx)?;}return Ok(false)}if let Some(merge)=self.merge.as_mut(){if merge.terminal_is_empty(){close_original_retained_step(cx,d,|_|{self.merge.take();Ok(RetainedCloneStep::Progress(receipt(d)))})?;}else{merge.close_step(cx)?;}return Ok(false)}close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){return self.retirement.select(self.body)?.step(g)}let slot=if self.args.is_some(){&mut self.args}else if self.input.is_some(){&mut self.input}else{&mut self.output};Ok(self.retirement.begin_granted(slot,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))})?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{(self.closing||self.taken)&&self.value.is_none()&&self.merge.is_none()&&self.args.is_none()&&self.input.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalUiArguments{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original UI argument continuation must return its source slots and close private outputs")}}
